    WS_OPCODE_PING          = 0x9,
    WS_OPCODE_PONG          = 0xa,
} ws_opcode;

typedef struct ws_frame_info {
    ws_opcode opcode;
    bool fin;
    bool masking;
    ws_close_reason reason;
    size_t frame_size;
    size_t payload_size;
